  debug_struct(f, "BuiltMatchTree", [
    ["branches", debug_vec(v.branches, f, debug_MatchTreeBranch)],
    ["otherwise_block", debug_BasicBlock(v.otherwise_block, f)],
    ["fake_borrow_temps", debug_vec(v.fake_borrow_temps, f, ((x, f) => debug_tuple(f, "", [debug_Place(x[0], f), debug_Local(x[1], f), debug_FakeBorrowKind(x[2], f)])))],
  ]);
